using System.Text.Json.Serialization;
using ActualLab.Rpc;
using ActualLab.Rpc.TypeScript;
using ActualLab.Tests;

namespace ActualLab.Fusion.Tests.TypeScriptRpc;

public class RpcTypeScriptGeneratorTest
{
    [Fact]
    public async Task GeneratesInterfacesDefinitionsAndDtos()
    {
        var result = await Generate(typeof(ITsGenTestService));

        result.Warnings.Should().BeEmpty();
        result.Code.Should().NotContain("\r");
        result.Code.Should().Be(
            """
            // <auto-generated>
            // Generated by ActualLab.Rpc.TypeScript. Don't edit it: change the .NET contracts and regenerate it instead.
            // </auto-generated>
            /* eslint-disable */

            import type { AsyncContext } from '@actuallab/core';
            import { defineRpcService, RpcType } from '@actuallab/rpc';

            export interface ITsGenTestService {
                Get(session: string, id: string, ctx?: AsyncContext): Promise<TsGenItem | null>;
                List(filter: TsGenFilter | null, ctx?: AsyncContext): Promise<TsGenPage<TsGenItem>>;
                OnUpsert(command: TsGen_Upsert): Promise<TsGenItem>;
                Ping(message: string): Promise<void>;
            }

            export const TsGenTestServiceDef = defineRpcService('ITsGenTestService', {
                Get: { args: ['', ''], callTypeId: 1 },
                List: { args: [{}], callTypeId: 1 },
                OnUpsert: { args: [{}] },
                Ping: { args: [''], returns: RpcType.noWait, wireArgCount: 1 },
            });

            export enum TsGenStatus {
                Draft = 0,
                Published = 5,
            }

            export interface TsGenItem {
                id: string;
                title: string;
                note: string | null;
                status: TsGenStatus;
                createdAt: string;
                priority: number | null;
                tags: string[];
                counters: Record<string, number>;
            }

            export interface TsGenFilter {
                text: string | null;
                statuses: TsGenStatus[];
            }

            export interface TsGenPage<T> {
                items: T[];
                total: number;
            }

            export interface TsGen_Upsert {
                session: string;
                item: TsGenItem;
            }

            """.ReplaceLineEndings("\n"));
    }

    [Fact]
    public async Task E2EContractsAreUpToDate()
    {
        // ts/e2e/ts-dotnet-e2e.ts uses these contracts, so TypeScriptRpcE2ETest verifies them on the wire
        var result = await Generate(typeof(ITypeScriptTestService), typeof(ITypeScriptTestComputeService));
        var path = Path.Combine(TypeScriptRunner.TsDir, "e2e", "contracts.generated.ts");
        var existingCode = File.Exists(path) ? (await File.ReadAllTextAsync(path)).ReplaceLineEndings("\n") : null;
        if (string.Equals(existingCode, result.Code, StringComparison.Ordinal))
            return;

        await File.WriteAllTextAsync(path, result.Code);
        Assert.Fail($"{path} was out of date, so it's regenerated now: review the change and rerun the test.");
    }

    [Fact]
    public async Task MatchesHandWrittenE2EDefinitions()
    {
        // Wire metadata of the hand-written definitions ts/e2e/ts-dotnet-e2e.ts used to have
        var result = await Generate(typeof(ITypeScriptTestService), typeof(ITypeScriptTestComputeService));

        result.Warnings.Should().BeEmpty();
        result.Code.Should().ContainAll(
            "    'Add:2': { args: [0, 0], wireArgCount: 2 },\n",
            "    'Add:3': { args: [0, 0, 0], wireArgCount: 3 },\n",
            "    Echo: { args: [''], wireArgCount: 1 },\n",
            "    GetSlowEchoInvocationCount: { args: [], wireArgCount: 0 },\n",
            "    Echo(message: string | null): Promise<string | null>;\n",
            "    GetCounter: { args: [''], callTypeId: 1 },\n",
            "    Set: { args: ['', 0] },\n",
            "    StreamInt32: { args: [0], returns: RpcType.stream, wireArgCount: 1 },\n",
            "    StreamInt32(count: number): Promise<RpcStream<number>>;\n",
            "import { defineRpcService, RpcType, type RpcStream } from '@actuallab/rpc';\n");
    }

    [Fact]
    public async Task HandlesEdgeCases()
    {
        var result = await Generate(typeof(ITsGenEdgeService));

        result.Code.Should().ContainAll(
            "    GetBox(): Promise<TsGenBox_Int32>;\n",
            "export interface TsGenBox_Int32 {\n    value: number;\n}",
            "    delete: number;\n    'x-y': number;\n",
            "    Process(function_: string): Promise<void>;\n",
            "export type TsGenColor = 'Red' | 'DarkBlue';",
            "export interface TsGenScalars {\n    symbol: string;\n    numbers: number[];\n    guid: string;\n"
            + "    amount: number;\n    duration: string;\n}");
        result.Code.Should().NotContain("Renamed");
        result.Warnings.Should().ContainSingle().Which.Should().Contain("ITsGenEdgeService.Renamed");
    }

    // Private methods

    private static async Task<RpcTypeScriptGeneratorResult> Generate(params Type[] serviceTypes)
    {
        var services = new ServiceCollection();
        var fusion = services.AddFusion();
        foreach (var serviceType in serviceTypes) {
            if (typeof(IComputeService).IsAssignableFrom(serviceType))
                fusion.AddClient(serviceType);
            else
                fusion.Rpc.AddClient(serviceType);
        }
        await using var serviceProvider = services.BuildServiceProvider();
        var serviceRegistry = serviceProvider.RpcHub().ServiceRegistry;
        return new RpcTypeScriptGenerator().Generate(serviceTypes.Select(t => serviceRegistry[t]));
    }
}

public interface ITsGenTestService : IComputeService
{
    [ComputeMethod]
    Task<TsGenItem?> Get(Session session, Ulid id, CancellationToken cancellationToken = default);
    [ComputeMethod]
    Task<TsGenPage<TsGenItem>> List(TsGenFilter? filter, CancellationToken cancellationToken = default);

    [CommandHandler]
    Task<TsGenItem> OnUpsert(TsGen_Upsert command, CancellationToken cancellationToken = default);
    Task<RpcNoWait> Ping(string message);
}

public interface ITsGenEdgeService : IRpcService
{
    Task<TsGenBox<int>> GetBox();
    Task<TsGenKeywords> GetKeywords();
    Task<TsGenScalars> GetScalars();
    Task Process(string function);
    [RpcMethod(Name = "Renamed")]
    Task<int> GetRenamed();
}

public enum TsGenStatus { Draft, Published = 5 }

[JsonConverter(typeof(JsonStringEnumConverter<TsGenColor>))]
public enum TsGenColor { Red, DarkBlue }

public sealed record TsGenItem(
    Ulid Id,
    string Title,
    string? Note,
    TsGenStatus Status,
    Moment CreatedAt,
    int? Priority,
    ImmutableArray<string> Tags,
    Dictionary<string, long> Counters);

public sealed record TsGenPage<T>(T[] Items, int Total);

public sealed record TsGenFilter(string? Text, TsGenStatus[] Statuses);

// ReSharper disable once InconsistentNaming
public sealed record TsGen_Upsert(Session Session, TsGenItem Item) : ISessionCommand<TsGenItem>;

public sealed record TsGenBox<T>(T Value) where T : struct;

public sealed record TsGenScalars(Symbol Symbol, ApiArray<int> Numbers, Guid Guid, decimal Amount, TimeSpan Duration);

public sealed record TsGenKeywords(
    [property: JsonPropertyName("delete")] int Delete,
    [property: JsonPropertyName("x-y")] int XY,
    TsGenColor Color);
